        "The medical domain also covers pain, vision, hearing, dentition, continence, sleep, bowels and immunisation - each drives function. [WHO ICOPE 2019]",
        "**Functional domain:** basic activities by Katz ADL and instrumental by Lawton IADL - function predicts outcome better than diagnosis. [Hazzard 8e]",
        "Loss of IADLs such as handling money and medication precedes loss of basic ADLs - **the earliest functional marker of dementia**. [Hazzard 8e]",
        "**Mobility and balance:** gait speed, Timed Up and Go, chair stand, footwear and walking aid - all five are modifiable. [WHO ICOPE 2019]",
        "Watch the patient get out of the chair and walk to the door - one observed transfer tells you more than any scale. [CDC STEADI 2017]",
        "**Cognition and mood:** one validated cognition screen plus one depression screen - each is missed if only the other is done. [WHO ICOPE 2019]",
        "Depression, delirium and dementia coexist - **finding one does not exclude the other two**. [Hazzard 8e]",
        "Untreated depression is the **commonest reversible cause** of apparent functional decline - so screen mood before labelling dementia. [Hazzard 8e]",
        "**Nutrition:** unintentional weight loss, MNA-SF, dentition and swallowing - weight loss precedes sarcopenia, falls and fracture. [ESPEN 2019]",
