        "**Katz ADL** covers bathing, dressing, toileting, transferring, continence and feeding, scored 0-6 - the six basic self-care tasks. [Hazzard 8e]",
        "Katz **6 = independent**, 4 = moderate impairment, 2 or less = severe dependence - each point lost converts into care hours. [Hazzard 8e]",
        "**Lawton IADL** has 8 items - telephone, shopping, cooking, housekeeping, laundry, transport, medication, finances - scored 0-8. [Hazzard 8e]",
        "**Barthel Index** (10 items, 0-100) is better for tracking rehabilitation after stroke or hip fracture - it detects small change. [Hazzard 8e]",
        "**MMSE** is scored out of 30 and 23 or less suggests impairment - it is weighted to language and orientation, not executive function. [Hazzard 8e]",
        "**MoCA** is scored out of 30 and under 26 is abnormal - add 1 point if education is 12 years or fewer, as schooling shapes the score. [Hazzard 8e]",
        "**Mini-Cog** is three-word recall plus clock drawing, scored 0-5, and 2 or less is positive - it takes 3 minutes, so it fits a clinic. [Hazzard 8e]",
