        "**Otago Exercise Programme** = leg strengthening plus balance retraining plus a walking plan, home-based.",
        "Otago is delivered as five supervised sessions and then continued by the patient.",
        "**Otago reduces falls by about 35% in the over-80s.**",
        "**Tai chi** produces a similar effect in the fitter older adult. [Cochrane Exercise Falls 2019]",
