        "**Advise single-vision distance glasses for walking outdoors**, not bifocals or varifocals.",
        "Treat corns, calluses, bunions and onychomycosis.",
        "Prescribe shoes with a **low broad heel, firm sole and a fastening** - not loose slippers or chappals.",
        "**Home hazard modification works best in high-risk patients**, done by an occupational therapist in the actual home. [NICE CG161]",
        "Fit grab rails beside the toilet and in the bathroom.",
        "Provide a **raised commode seat instead of a squat pan**.",
        "Non-slip mats and floor drainage; remove loose rugs and thresholds.",
        "Handrails on both sides of the stairs, and a bedside lamp or night light.",
        "A bedside urinal or commode removes the night walk to the toilet.",
        "Move daily items to waist height.",
        "**Bone health:** assess fracture risk with **FRAX**, using the Indian population where available.",
        "Give **calcium 1000-1200 mg and vitamin D 800-1000 IU daily** where intake is inadequate.",
