        "**Sarcopenia** is loss of muscle mass and strength - may occur at any weight.",
        "**Sarcopenic obesity** is common and easily missed.",
        "**Cachexia** is a complex metabolic syndrome of underlying illness - weight loss, inflammation, insulin resistance and increased protein breakdown.",
