      marks: 5,
      minutes: 10,
      frequency: "less-common",
      question: "Write short notes on the assessment of nutritional status in the elderly and the prevention of refeeding syndrome.",
      openingLines: [
        "Undernutrition is common, under-recognised and reversible in older adults, and it drives sarcopenia, falls, pressure injury, delayed wound healing, infection and death; assessment therefore belongs in every geriatric consultation.",
        "Because the physical signs are late, assessment relies on a weight trend, a validated screening tool and a search for the cause rather than on any single measurement.",
      ],
      answer: [
        {
          heading: "1. Screening and anthropometry",
          points: [
            "Weigh at every visit and plot the trend; unintentional loss of more than 5% in six months or 10% at any time is significant.",
            "Mini Nutritional Assessment short form, scored 0-14: 12-14 normal, 8-11 at risk, 0-7 malnourished; the full MNA scores 0-30.",
            "BMI, remembering that below 22 kg/m2 is a concern in older adults; mid-upper arm circumference and calf circumference where height or weight cannot be measured.",
            "Look for oedema and ascites, which mask weight loss, and for sarcopenic obesity, in which muscle is lost at a normal or high body weight.",
          ],
        },
        {
          heading: "2. Clinical assessment and causes",
          points: [
            "Dietary history including who buys and cooks the food, the number of meals, and affordability.",
            "Examination of the mouth, teeth, dentures and swallow; screen for dysphagia.",
            "Search for causes with the **MEALS ON WHEELS** mnemonic - drugs, depression, dementia, dysphagia, oral disease, poverty, endocrine and enteric disease, restrictive diets.",
            "Investigations: haemogram, CRP, glucose, renal and liver function, calcium, thyroid function.",
            "**Albumin is a marker of illness rather than of intake.**",
            "Vitamin B12 and vitamin D - and screening for tuberculosis and malignancy where indicated.",
          ],
        },
        {
          heading: "3. Refeeding syndrome - risk, mechanism and prevention",
          points: [
            "Mechanism: after prolonged starvation, refeeding causes an **insulin surge** that drives phosphate, potassium and magnesium into cells - with thiamine consumption.",
            "Result: hypophosphataemia, arrhythmia, cardiac failure, respiratory failure, rhabdomyolysis, seizures and Wernicke encephalopathy.",
            "High risk: **BMI under 16 kg/m2**, unintentional weight loss over 15% in 3-6 months. [NICE CG32]",
            "High risk: little or no nutritional intake for more than 10 days, or low potassium, phosphate or magnesium before feeding. [NICE CG32]",
            "Also at risk: chronic alcohol use and long-term diuretic, insulin or chemotherapy use. [NICE CG32]",
            "Prevention: check and correct electrolytes before feeding, give thiamine 200-300 mg daily and a vitamin B complex before and during the first ten days.",
            "Start feeding at 10 kcal/kg/day, or 5 kcal/kg/day in extreme risk, increasing slowly to full requirement over 4-7 days.",
            "Monitor phosphate, potassium, magnesium, glucose, fluid balance and cardiac status daily for the first week and replace deficits promptly.",
          ],
        },
      ],
