        "**Bereavement care is part of palliative care and part of family medicine** - make a follow-up contact with the family after the death.",
        "Screen for **prolonged grief disorder** - persistent intense yearning and preoccupation with functional impairment beyond about 12 months in adults - it needs referral.",
        "**The surviving spouse of an older patient is now a high-risk patient of your own practice.**",
